import React, { useState, useEffect, useRef } from 'react';
import './AgentWorkspace.css';
import { connectWebSocket, sendWebSocketCommand } from '../../services/websocket';

const AgentWorkspace = ({ initialContext = {} }) => {
    const [state, setState] = useState({
        goals: [],
        thoughts: [],
        toolCalls: [],
        status: 'idle',
        error: null
    });

    const [goal, setGoal] = useState('');
    const wsRef = useRef(null);

    // Format timestamp to readable time
    const formatTime = (timestamp) => {
        if (!timestamp) return '';
        const date = new Date(timestamp * 1000);
        return date.toLocaleTimeString('en-US', { 
            hour: '2-digit', 
            minute: '2-digit', 
            second: '2-digit',
            hour12: false
        });
    };

    // Handle WebSocket message
    const handleWebSocketMessage = (data) => {
        if (data && data.event_type) {
            handleAgentUpdate(data);
        }
    };

    // Connect to WebSocket on component mount
    useEffect(() => {
        // Connect to WebSocket with callback
        const ws = connectWebSocket(handleWebSocketMessage);
        wsRef.current = ws;

        // Clean up on unmount
        return () => {
            if (wsRef.current) {
                wsRef.current.close();
            }
        };
    }, []);

    // Handle agent state updates
    const handleAgentUpdate = (update) => {
        const { event_type, data } = update;

        switch (event_type) {
            case 'thought_added':
                setState(prevState => ({
                    ...prevState,
                    thoughts: [...prevState.thoughts, data.thought]
                }));
                break;

            case 'tool_started':
                setState(prevState => ({
                    ...prevState,
                    toolCalls: [...prevState.toolCalls, data.tool_call]
                }));
                break;

            case 'tool_completed':
                setState(prevState => ({
                    ...prevState,
                    toolCalls: prevState.toolCalls.map(tc => 
                        tc.id === data.tool_call_id 
                            ? { ...tc, outputs: data.outputs, end_time: Date.now() / 1000 }
                            : tc
                    )
                }));
                break;

            case 'tool_failed':
                setState(prevState => ({
                    ...prevState,
                    toolCalls: prevState.toolCalls.map(tc => 
                        tc.id === data.tool_call_id 
                            ? { ...tc, error: data.error, end_time: Date.now() / 1000 }
                            : tc
                    )
                }));
                break;

            case 'status_changed':
                setState(prevState => ({
                    ...prevState,
                    status: data.status
                }));
                break;

            case 'goal_set':
                setState(prevState => ({
                    ...prevState,
                    goals: [...prevState.goals, data.goal]
                }));
                break;

            case 'goal_completed':
                setState(prevState => ({
                    ...prevState,
                    goals: prevState.goals.map(g => 
                        g.id === data.goal_id 
                            ? { ...g, completed: true }
                            : g
                    )
                }));
                break;

            case 'error':
                setState(prevState => ({
                    ...prevState,
                    error: data.error
                }));
                break;

            case 'state_reset':
                setState({
                    goals: [],
                    thoughts: [],
                    toolCalls: [],
                    status: 'idle',
                    error: null
                });
                break;

            default:
                console.log('Unknown event type:', event_type);
        }
    };

    // Handle goal submission
    const handleGoalSubmit = (e) => {
        e.preventDefault();
        console.log("Form submitted with goal:", goal);

        if (!goal.trim()) {
            console.error("Goal is empty, not submitting");
            return;
        }

        // Send command to start agent
        if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
            console.log("Sending start command via WebSocket");
            sendWebSocketCommand(wsRef.current, {
                type: 'start',
                goal: goal,
                context: initialContext
            });

            // Reset input field after sending
            setGoal('');
        } else {
            console.error('WebSocket is not connected, readyState:', wsRef.current ? wsRef.current.readyState : 'null');
        }
    };

    // Handle stopping the agent
    const handleStopAgent = () => {
        if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
            sendWebSocketCommand(wsRef.current, {
                type: 'stop'
            });
        }
    };

    // Handle resetting the agent
    const handleResetAgent = () => {
        if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
            sendWebSocketCommand(wsRef.current, {
                type: 'reset'
            });
        }
    };

    // Find tool calls for a thought
    const getToolsForThought = (thoughtId) => {
        return state.toolCalls.filter(tc => tc.thought_id === thoughtId);
    };

    // Get tool names used in a thought
    const getToolNamesForThought = (thoughtId) => {
        const tools = getToolsForThought(thoughtId);
        return [...new Set(tools.map(t => t.tool_name))];
    };

    return (
        <div className="agent-workspace">
            <header className="workspace-header">
                <h1>Agent Reasoning Process</h1>
                <form className="agent-controls" onSubmit={handleGoalSubmit}>
                    <input 
                        type="text" 
                        placeholder="Enter goal for the agent..." 
                        value={goal}
                        onChange={(e) => setGoal(e.target.value)}
                        disabled={state.status !== 'idle'}
                    />
                    <button 
                        type="submit"
                        disabled={state.status !== 'idle'}
                    >
                        Start
                    </button>
                    <button 
                        type="button"
                        onClick={handleStopAgent}
                        disabled={!['thinking', 'executing-tool'].includes(state.status)}
                    >
                        Stop
                    </button>
                    <button 
                        type="button"
                        onClick={handleResetAgent}
                        disabled={state.status === 'thinking' || state.status === 'executing-tool'}
                    >
                        Reset
                    </button>
                </form>
                <div className="agent-status">
                    Status: <span className={`status-${state.status}`}>{state.status}</span>
                    {state.error && <span className="error-message">Error: {state.error}</span>}
                </div>
            </header>

            <div className="workspace-content">
                <div className="workspace-main">
                    <div className="agent-reasoning-header">
                        <h2>Agent Reasoning Process</h2>
                        <div className="reasoning-stats">
                            Total steps: {state.thoughts.length} | Tool calls: {state.toolCalls.length}
                        </div>
                    </div>
                    <div className="reasoning-container">
                        {state.thoughts.map(thought => {
                            const toolsUsed = getToolNamesForThought(thought.id);
                            return (
                                <div key={thought.id} className="thought-card">
                                    <div className="thought-header">
                                        <pre>{thought.content}</pre>
                                        <div className="thought-time">{formatTime(thought.timestamp)}</div>
                                    </div>

                                    {toolsUsed.length > 0 && (
                                        <div className="tools-used">
                                            <span>Tools used:</span>
                                            {toolsUsed.map(tool => (
                                                <span key={tool} className="tool-badge">{tool}</span>
                                            ))}
                                        </div>
                                    )}

                                    {/* Display tool calls related to this thought */}
                                    {getToolsForThought(thought.id).map(toolCall => (
                                        <div key={toolCall.id} className="tool-call-card">
                                            <div className="tool-call-header">
                                                <h4>{toolCall.tool_name}</h4>
                                                {toolCall.outputs && (
                                                    <div className="tool-status">
                                                        <span className="status-completed-badge">
                                                            <span>✓</span> completed
                                                        </span>
                                                    </div>
                                                )}
                                            </div>

                                            <div className="tool-call-content">
                                                <h5>Inputs:</h5>
                                                <pre>{JSON.stringify(toolCall.inputs, null, 2)}</pre>
                                            </div>

                                            {toolCall.outputs && (
                                                <div className="tool-call-content">
                                                    <h5>Outputs:</h5>
                                                    <pre>{JSON.stringify(toolCall.outputs, null, 2)}</pre>
                                                </div>
                                            )}

                                            {toolCall.error && (
                                                <div className="tool-call-content tool-error">
                                                    <h5>Error:</h5>
                                                    <pre>{toolCall.error}</pre>
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="workspace-sidebar">
                    <div className="goals-panel">
                        <h2>Goals</h2>
                        <ul>
                            {state.goals.map(goal => (
                                <li key={goal.id} className={goal.completed ? 'completed' : ''}>
                                    {goal.description}
                                    {goal.completed && <span className="completed-badge">✓</span>}
                                </li>
                            ))}
                        </ul>
                    </div>

                    <div className="tool-execution-panel">
                        <h2>Tool Executions</h2>
                        <ul>
                            {state.toolCalls.map(toolCall => (
                                <li key={toolCall.id} className={toolCall.outputs ? 'completed' : toolCall.error ? 'error' : 'running'}>
                                    {toolCall.tool_name}
                                    {toolCall.outputs && <span className="completed-badge">✓</span>}
                                    {toolCall.error && <span className="error-badge">✗</span>}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AgentWorkspace;
